  "source": "namespace SelectorBound\n\nabbrev Var (m n : Nat) := Sum (Fin m) (Fin n)\nabbrev Clause (m n : Nat) := List (Var m n × Bool)\n\ndef Holds {m n : Nat} (a : Var m n → Bool) (c : Clause m n) : Prop :=\n  ∃ l ∈ c, a l.1 = l.2\n\n/-- The m positive-selector clauses and n negative-selector clauses. -/\ndef Selected {m n : Nat} (a : Var m n → Bool) (z : Bool) : Prop :=\n  (∀ i, z = true ∨ a (.inl i) = true) ∧\n  (∀ j, z = false ∨ a (.inr j) = true)\n\ndef pairClause {m n : Nat} (p : Fin m × Fin n) : Clause m n :=\n  [(.inl p.1, true), (.inr p.2, true)]\n\ntheorem project {m n : Nat} (a : Var m n → Bool) :\n    (∃ z, Selected a z) ↔ (∀ i, a (.inl i) = true) ∨ (∀ j, a (.inr j) = true) := by\n  constructor\n  · rintro ⟨z, hp, hn⟩\n    cases z with\n    | false => exact Or.inl (by simpa using hp)\n    | true => exact Or.inr (by simpa using hn)\n  · rintro (h | h)\n    · exact ⟨false, fun i => Or.inr (h i), fun _ => Or.inl rfl⟩\n    · exact ⟨true, fun _ => Or.inl rfl, fun j => Or.inr (h j)⟩\n\ntheorem pair_holds {m n : Nat} (a : Var m n → Bool) (p : Fin m × Fin n) :\n    Holds a (pairClause p) ↔ a (.inl p.1) = true ∨ a (.inr p.2) = true := by\n  simp [Holds, pairClause]\n\n/-- The assignment with exactly one hole in each block. -/\ndef hole {m n : Nat} (p : Fin m × Fin n) : Var m n → Bool\n  | .inl i => decide (i ≠ p.1)\n  | .inr j => decide (j ≠ p.2)\n\ndef join {m n : Nat} (a b : Var m n → Bool) (v : Var m n) : Bool := a v || b v\n\ntheorem hole_fails {m n : Nat} (p : Fin m × Fin n) : ¬ ∃ z, Selected (hole p) z := by\n  intro h\n  rcases (project _).mp h with left | right\n  · simpa [hole] using left p.1\n  · simpa [hole] using right p.2\n\ntheorem join_projects {m n : Nat} (p q : Fin m × Fin n) (hne : p ≠ q) :\n    ∃ z, Selected (join (hole p) (hole q)) z := by\n  apply (project _).mpr\n  by_cases hi : p.1 = q.1\n  · have hj : p.2 ≠ q.2 := fun h => hne (Prod.ext hi h)\n    right\n    intro j\n    by_cases h : j = p.2\n    · simpa [join, hole, h] using hj\n    · simp [join, hole, h]\n  · left\n    intro i\n    by_cases h : i = p.1\n    · simpa [join, hole, h] using hi\n    · simp [join, hole, h]\n\n/-- The assignments falsifying one signed clause are closed under Boolean OR. -/\ntheorem join_fails {m n : Nat} (c : Clause m n) (a b : Var m n → Bool)\n    (ha : ¬ Holds a c) (hb : ¬ Holds b c) : ¬ Holds (join a b) c := by\n  rintro ⟨⟨v, s⟩, mem, eq⟩\n  have na : a v ≠ s := fun h => ha ⟨(v,s), mem, h⟩\n  have nb : b v ≠ s := fun h => hb ⟨(v,s), mem, h⟩\n  change (a v || b v) = s at eq\n  cases av : a v <;> cases bv : b v <;> cases s <;> simp_all\n\n/-- All mn binary resolvents suffice, and no equivalent CNF over the retained\n    variables can use fewer clauses, even with unrestricted signs or widths. -/\ntheorem tight_projection (m n : Nat) :\n    (∀ a : Var m n → Bool, (∀ p, Holds a (pairClause p)) ↔ ∃ z, Selected a z) ∧\n    (∀ (k : Nat) (f : Fin k → Clause m n),\n      (∀ a, (∀ t, Holds a (f t)) ↔ ∃ z, Selected a z) → m * n ≤ k) := by\n  classical\n  constructor\n  · intro a\n    rw [project]\n    constructor\n    · intro h\n      by_cases left : ∀ i, a (.inl i) = true\n      · exact Or.inl left\n      · obtain ⟨i, hi⟩ := Classical.not_forall.mp left\n        exact Or.inr (fun j => ((pair_holds _ (i,j)).mp (h (i,j))).resolve_left hi)\n    · rintro (left | right) p\n      · exact (pair_holds _ _).mpr (Or.inl (left p.1))\n      · exact (pair_holds _ _).mpr (Or.inr (right p.2))\n  · intro k f represents\n    have fails (p : Fin m × Fin n) : ∃ t, ¬ Holds (hole p) (f t) :=\n      Classical.not_forall.mp (fun all => hole_fails p ((represents _).mp all))\n    let index (p : Fin m × Fin n) : Fin k := Classical.choose (fails p)\n    have bad (p : Fin m × Fin n) : ¬ Holds (hole p) (f (index p)) :=\n      Classical.choose_spec (fails p)\n    have injective : Function.Injective index := by\n      intro p q same\n      by_contra ne\n      have bq : ¬ Holds (hole q) (f (index p)) := same.symm ▸ bad q\n      exact (join_fails _ _ _ (bad p) bq) ((represents _).mpr (join_projects p q ne) (index p))\n    simpa using Fintype.card_le_of_injective index injective\n\nend SelectorBound\n\n",
  "theorem": "SelectorBound.tight_projection",
  "dependencies": []
}
